from lib import *
S = SS('x1')
steps = [
    step("refresh() 的 12 个步骤逐步记录(Spring Framework 7.0.9,AnnotationConfigApplicationContext,配置里 9 个 @Bean)。refresh 之前只有 6 个 BeanDefinition(5 个内部处理器加配置类本身),prepareBeanFactory 注册了 4 个现成的单例:environment、systemProperties、systemEnvironment、applicationStartup。invokeBeanFactoryPostProcessors 把 BeanDefinition 从 6 个涨到 15 个(@Bean 方法在这里才变成定义),用了 76456 µs,是最慢的一步。initMessageSource 26916 µs,finishBeanFactoryInitialization 11373 µs(单例 14 个变 20 个),finishRefresh 8001 µs。", t=tl(S(1)), mark=lidx(S(1), 'invokeBeanFactoryPostProcessors  ', 'finishBeanFactoryInitialization  '), done=lidx(S(1), 'prepareBeanFactory  ', 'registerBeanPostProcessors  '), b=bars([['invokeBeanFactoryPostProcessors µs', 76456, '76456'], ['initMessageSource µs', 26916, '26916'], ['finishBeanFactoryInitialization µs', 11373, '11373'], ['finishRefresh µs', 8001, '8001'], ['registerBeanPostProcessors µs', 4683, '4683'], ['prepareBeanFactory µs', 4081, '4081']], 76456, mark=[0], cur=[1, 2, 3], done=[4, 5]), kv=KV([['refresh 前', '6 个 BeanDefinition'], ['invokeBeanFactoryPostProcessors 后', '15 个(@Bean 在这一步变成定义)'], ['单例', '0 → 21'], ['最慢的一步', '76456 µs']], ['最慢的一步'])),
    step("回调和 Bean 的创建分别在哪一步。Bfpp(BeanFactoryPostProcessor)的构造和 postProcessBeanFactory 都在 invokeBeanFactoryPostProcessors 里,它被调用时 BeanDefinition 已有 15 个、单例 9 个。Bpp(BeanPostProcessor)的构造在 registerBeanPostProcessors 里。A、B、Life、Init 这些普通单例都在 finishBeanFactoryInitialization 里按顺序创建:A 先于依赖它的 B。SmartInitializingSingleton 的回调紧跟其后,Life.start() 和 ContextRefreshedEvent 在 finishRefresh。prototype 的 Proto 与 @Lazy 的 LazyOne 在 refresh 期间都没有创建,第一次 getBean 才创建(Proto 每次一个新的)。close() 时 Life.stop(),然后 B 先于 A 销毁。", t=tl(S(2)), mark=lidx(S(2), '构造 Bfpp', '构造 Bpp', '构造 LazyOne'), done=lidx(S(2), '构造 A', '构造 B(依赖 A)', 'Life.start()', 'ContextRefreshedEvent', 'B.@PreDestroy'), b=bars([['Bfpp 的构造所在步骤', 5, 'invokeBeanFactoryPostProcessors'], ['Bpp 的构造所在步骤', 6, 'registerBeanPostProcessors'], ['A、B 等单例所在步骤', 11, 'finishBeanFactoryInitialization'], ['Life.start() 所在步骤', 12, 'finishRefresh']], 12, mark=[0, 1], done=[2, 3]), kv=KV([['BeanFactoryPostProcessor', 'invokeBeanFactoryPostProcessors 里构造并调用'], ['普通单例', 'finishBeanFactoryInitialization,依赖先创建'], ['prototype / @Lazy', 'refresh 期间不创建'], ['close()', 'B 先于 A 销毁']], ['普通单例'])),
    step("refresh 失败时。Needs 依赖一个没有注册的 Missing:前 10 个步骤(到 registerListeners)都完成了,在 finishBeanFactoryInitialization 里先创建了 A,再创建 needs 时抛 UnsatisfiedDependencyException。随后 A 的 @PreDestroy 被调用,上下文 isActive 为 false。refresh 失败不会留下半个活着的容器,已经创建的单例会被销毁。", t=tl(S(3)), mark=lidx(S(3), '异常 UnsatisfiedDependencyException'), done=lidx(S(3), '构造 A', 'A.@PreDestroy'), b=bars([['失败前完成的步骤数', 10, '10'], ['失败时已创建的单例 A', 1, '1'], ['A 的 @PreDestroy 调用次数', 1, '1']], 12, cur=[0], mark=[1], done=[2]), kv=KV([['异常', 'UnsatisfiedDependencyException'], ['发生步骤', 'finishBeanFactoryInitialization'], ['已创建的 A', '被销毁(@PreDestroy)'], ['isActive', 'false']], ['已创建的 A'])),
    step("同一个上下文 refresh 两次。第一次完整走完 12 个步骤;第二次只执行了 prepareRefresh 就抛出 IllegalStateException: GenericApplicationContext does not support multiple refresh attempts: just call 'refresh' once。AnnotationConfigApplicationContext 是 GenericApplicationContext 的子类,只能刷新一次;XML 上下文是否允许多次 refresh 这里没有测。", t=tl(S(4)), mark=lidx(S(4), '第二次 refresh'), b=bars([['第一次 refresh 完成的步骤数', 12, '12'], ['第二次 refresh 完成的步骤数', 0, '0(只进了 prepareRefresh)']], 12, done=[0], mark=[1]), kv=KV([['第一次', '12 步全部完成'], ['第二次', 'IllegalStateException'], ['提示', "just call 'refresh' once"], ['XML 上下文', '没有测']], ['第二次'])),
]
A = mkartx('x1', 1, 'Spring,IoC,ApplicationContext,refresh,容器启动,真实验证,动画演示',
    '实测 ApplicationContext.refresh() 的 12 个步骤:BeanDefinition 在 invokeBeanFactoryPostProcessors 里从 6 个涨到 15 个(最慢的一步,76456 µs);BeanFactoryPostProcessor、BeanPostProcessor 本身最先被创建;普通单例在 finishBeanFactoryInitialization 里创建,prototype 与 @Lazy 的 Bean 不创建;refresh 失败时已创建的单例会被销毁。',
    '容器启动时到底做了什么?@Bean 方法是什么时候变成 Bean 的?BeanFactoryPostProcessor 和 BeanPostProcessor 在哪一步被创建?失败了会怎样?这篇把 refresh() 的每一步重写一遍加上计数和时间线,用 Spring Framework 7.0.9 逐步量出来。',
    [('6 → 15', 'invokeBeanFactoryPostProcessors 一步里 BeanDefinition 的数量(@Bean 方法在这里才变成定义)'), ('76456 µs', 'refresh 12 个步骤里最慢的一步(invokeBeanFactoryPostProcessors)'), ('10 步', 'refresh 失败之前已经完成的步骤数(第 11 步 finishBeanFactoryInitialization 抛出异常)')],
    [('十二个步骤', '<p>每一步前后的 BeanDefinition 数和单例数、耗时都记下来:定义在第 5 步涨,单例分批增加。</p>'),
     ('回调发生在哪一步', '<p>BeanFactoryPostProcessor 与 BeanPostProcessor 最早创建;普通单例在 finishBeanFactoryInitialization 按依赖顺序创建;prototype 与 @Lazy 不在 refresh 里创建。</p>'),
     ('失败了会怎样', '<p>refresh 抛异常时,已经创建的单例会被销毁,上下文不再活跃。</p>'),
     ('只能刷新一次', '<p>GenericApplicationContext 的第二次 refresh 直接抛 IllegalStateException。</p>')],
    steps,
    [ENV_X + '。用的是不带 Boot 的 Spring Framework 7.0.9 的 AnnotationConfigApplicationContext;把 refresh() 里的各个受保护方法重写后在前后插入计数,重写本身有微小的额外开销,µs 数字每次运行会变(例如 invokeBeanFactoryPostProcessors 在几次运行里是 62942 到 76456 µs);Bean 名字里的 main.Conf 是内部类 demo.Main$Conf 的默认名字',
     '没有验证:Spring Boot 的 SpringApplication 上下文(在 onRefresh 里创建内嵌 Web 服务器,见后面的 Boot 篇);ClassPathXmlApplicationContext 是否允许多次 refresh;ConfigurationClassPostProcessor 解析 @Bean 的内部过程;BeanDefinitionRegistryPostProcessor 的先后顺序;大型应用里各步骤的耗时分布'],
    'ApplicationContext.refresh() 的十二步')
